{"path": "/private/tmp/prompt_demos/runs_flash-demos-plus/workspaces/01/lib.mbt", "content": "// TOML subset parser — produces a deterministic JSON value.
// Supported:
//   - comments (#)
//   - blank lines and whitespace
//   - bare keys and dotted keys
//   - tables ([owner], [database.settings])
//   - string escapes: \", \\, \n, \t
//   - integers, booleans, arrays of those values
//   - duplicate-key errors with a useful message

///| Error type for parsing failures.
suberror TomlError {
  ParseError(String)
} derive(Debug, Show)

///| Parse TOML text into a Json value.
/// Returns a Json::Object(map) where top-level tables are nested under their keys.
pub fn parse_toml(input : String) -> Json raise TomlError {
  let lines = input.split("\n")
  let mut root : Map[String, Json] = Map::new()
  let mut current_table : Map[String, Json] = root
  let mut current_prefix : String? = None

  for i in 0..<lines.length() {
    let line = lines[i]
    let trim = line.trim()

    // blank line or comment
    if trim.is_empty() || trim[0] is '#' {
      continue
    }

    // table header
    if trim[0] is '[' {
      let table_part = trim.sub(start=1, end=trim.length()).trim()
      if !(table_part[table_part.length() - 1] is ']') {
        raise TomlError::ParseError(
          "line \{i + 1}: malformed table header: missing ']'",
        )
      }
      let key_part = table_part.sub(start=0, end=table_part.length() - 1).trim()
      let keys = split_dotted_key(key_part)
      current_prefix = Some(key_part)
      current_table = root
      // navigate to the nested table, creating empty maps as needed
      for j in 0..<keys.length() {
        let k = keys[j]
        if current_table.contains(k) {
          match current_table[k] {
            Json::Object(sub) => current_table = sub
            _ =>
              raise TomlError::ParseError(
                "line \{i + 1}: key '\{k}' is not a table",
              )
          }
        } else {
          let sub : Map[String, Json] = Map::new()
          current_table[k] = Json::Object(sub)
          current_table = sub
        }
      }
      continue
    }

    // key-value pair
    let eq_pos = find_unquoted_eq(trim)
    if eq_pos < 0 {
      raise TomlError::ParseError(
        "line \{i + 1}: invalid key-value pair: missing '='",
      )
    }
    let raw_key = trim.sub(start=0, end=eq_pos).trim()
    let raw_value = trim.sub(start=eq_pos + 1, end=trim.length()).trim()
    let keys = split_dotted_key(raw_key)
    let value = parse_value(raw_value, i + 1)?

    // insert value into current_table, creating nested maps for dotted keys
    set_nested(current_table, keys, value) catch {
      err @ TomlError::ParseError(msg) =>
        raise TomlError::ParseError("line \{i + 1}: \{msg}")
    }
  }

  Json::Object(root)
}

///| Find first unquoted `=` outside of string literals.
fn find_unquoted_eq(s : StringView) -> Int {
  let mut depth = 0
  let mut in_str = false
  let mut i = 0
  while i < s.length() {
    let ch = s[i]
    if in_str {
      if ch is '"' {
        in_str = false
      }
    } else {
      if ch is '"' {
        in_str = true
      } else if ch is '=' && depth is 0 {
        return i
      }
    }
    i += 1
  }
  -1
}

///| Split a dotted key into parts.
fn split_dotted_key(key : StringView) -> Array[String] {
  let mut parts : Array[String] = []
  let mut start = 0
  let mut i = 0
  while i < key.length() {
    if key[i] is '.' {
      parts.push(key.sub(start=start, end=i).trim().to_owned())
      start = i + 1
    }
    i += 1
  }
  parts.push(key.sub(start=start, end=i).trim().to_owned())
  parts
}

///| Parse a TOML value into Json.
fn parse_value(s : StringView, line : Int) -> Json raise TomlError {
  let text = s.to_owned()
  // array
  if text[0] is '[' {
    return parse_array(text, line)
  }
  // quoted string
  if text[0] is '"' {
    return Json::String(parse_string(text, line))
  }
  // boolean
  if text == "true" {
    return Json::True
  }
  if text == "false" {
    return Json::False
  }
  // integer
  let n : Int = @string.from_str(text) catch {
    _ =>
      raise TomlError::ParseError(
        "line \{line}: cannot parse value: '\{text}'",
      )
  }
  Json::number(n.to_double(), repr=text)
}

///| Parse a TOML array.
fn parse_array(text : String, line : Int) -> Json raise TomlError {
  let inner = text.sub(start=1, end=text.length()).trim()
  if !(inner[inner.length() - 1] is ']') {
    raise TomlError::ParseError(
      "line \{line}: malformed array: missing ']'",
    )
  }
  let content = inner.sub(start=0, end=inner.length() - 1).trim()
  if content.is_empty() {
    return Json::Array([])
  }
  let mut arr : Array[Json] = []
  let mut i = 0
  let len = content.length()
  while i < len {
    // skip whitespace
    while i < len && content[i] is ' ' {
      i += 1
    }
    if i >= len {
      break
    }
    // detect value start
    let start = i
    if content[i] is '"' {
      // string element: scan to closing "
      i += 1
      while i < len && !(content[i] is '"') {
        if content[i] is '\\' {
          i += 1 // skip escaped char
        }
        i += 1
      }
      i += 1 // closing "
    } else if content[i] is '[' {
      // nested array: count brackets
      let mut depth = 1
      i += 1
      while i < len && depth > 0 {
        if content[i] is '[' {
          depth += 1
        } else if content[i] is ']' {
          depth -= 1
        }
        i += 1
      }
    } else {
      // number, bool, etc – scan to comma or end
      while i < len && !(content[i] is ',' | ']') {
        i += 1
      }
    }
    let elem_text = if i < len && content[i] is ',' {
      content.sub(start=start, end=i).trim().to_owned()
    } else {
      content.sub(start=start, end=i).trim().to_owned()
    }
    arr.push(parse_value(elem_text, line)?)
    // skip comma
    if i < len && content[i] is ',' {
      i += 1
    }
  }
  if i < len && content[i] is ']' {
    // trailing comma or leftover bracket, skip
  }
  Json::Array(arr)
}

///| Parse a TOML quoted string, handling escapes.
fn parse_string(text : String, line : Int) -> String raise TomlError {
  if text.length() < 2 || text[0] isnt '"' {
    raise TomlError::ParseError("line \{line}: expected quoted string")
  }
  let end = text.length() - 1
  if text[end] isnt '"' {
    raise TomlError::ParseError(
      "line \{line}: string missing closing quote",
    )
  }
  let inner = text.sub(start=1, end=end)
  let mut out = StringBuilder::new()
  let mut i = 0
  while i < inner.length() {
    let ch = inner[i]
    if ch is '\\' {
      i += 1
      if i >= inner.length() {
        raise TomlError::ParseError(
          "line \{line}: trailing backslash in string",
        )
      }
      match inner[i] {
        '"' => out.write_char('"')
        '\\' => out.write_char('\\')
        'n' => out.write_char('\n')
        't' => out.write_char('\t')
        c =>
          raise TomlError::ParseError(
            "line \{line}: invalid escape '\\\{c}'",
          )
      }
    } else {
      out.write_char(ch.to_char())
    }
    i += 1
  }
  out.to_string()
}

///| Set a value at a dotted key path, creating nested tables as needed.
fn set_nested(
  map : Map[String, Json],
  keys : Array[String],
  value : Json
) -> Unit raise TomlError {
  if keys.is_empty() {
    raise TomlError::ParseError("empty key")
  }
  if keys.length() == 1 {
    let k = keys[0]
    if map.contains(k) {
      raise TomlError::ParseError("duplicate key: '\{k}'")
    }
    map[k] = value
    return
  }
  let first = keys[0]
  let rest = keys[1..]
  if map.contains(first) {
    match map[first] {
      Json::Object(sub) => set_nested(sub, rest, value)?
      _ =>
        raise TomlError::ParseError(
          "key '\{first}' is not a table",
        )
    }
  } else {
    let sub : Map[String, Json] = Map::new()
    map[first] = Json::Object(sub)
    set_nested(sub, rest, value)?
  }
}
"}

{"path": "/private/tmp/prompt_demos/runs_flash-demos-plus/workspaces/01/test.mbt", "content": "// Black-box tests for the TOML parser.

///|
test "empty input" {
  let result = parse_toml("")
  match result {
    Json::Object(map) => assert_eq(map.size(), 0)
    _ => fail("expected object")
  }
}

///|
test "comment and blank lines" {
  let result = parse_toml(
    #|# this is a comment
    |
    |  # indented comment
    |key = 42
    |
  )
  let expect = Json::object(Map::of([("key", Json::number(42.0, repr="42"))]))
  assert_eq(result, expect)
}

///|
test "bare key integer value" {
  let result = parse_toml("name = 42")
  let expect = Json::object(Map::of([("name", Json::number(42.0, repr="42"))]))
  assert_eq(result, expect)
}

///|
test "string value" {
  let result = parse_toml(#|title = "Hello, TOML!"|#)
  let expect = Json::object(Map::of([("title", Json::string("Hello, TOML!"))]))
  assert_eq(result, expect)
}

///|
test "string escapes" {
  let result = parse_toml(#|msg = "line1\nline2\ttab \"quote\" \\back"|#)
  let expect = Json::object(Map::of([(
    "msg",
    Json::string("line1\nline2\ttab \"quote\" \\back"),
  )]))
  assert_eq(result, expect)
}

///|
test "boolean values" {
  let result = parse_toml(
    #|a = true
    |b = false
  )
  let expect = Json::object(Map::of([
    ("a", Json::True),
    ("b", Json::False),
  ]))
  assert_eq(result, expect)
}

///|
test "array of integers" {
  let result = parse_toml("ports = [8000, 8001, 8002]")
  let expect = Json::object(Map::of([(
    "ports",
    Json::array([
      Json::number(8000.0, repr="8000"),
      Json::number(8001.0, repr="8001"),
      Json::number(8002.0, repr="8002"),
    ]),
  )]))
  assert_eq(result, expect)
}

///|
test "array of booleans" {
  let result = parse_toml("flags = [true, false, true]")
  let expect = Json::object(Map::of([(
    "flags",
    Json::array([Json::True, Json::False, Json::True]),
  )]))
  assert_eq(result, expect)
}

///|
test "array of strings" {
  let result = parse_toml(#|names = ["a", "b", "c"]|#)
  let expect = Json::object(Map::of([(
    "names",
    Json::array([Json::string("a"), Json::string("b"), Json::string("c")]),
  )]))
  assert_eq(result, expect)
}

///|
test "dotted key" {
  let result = parse_toml("x.y.z = 1")
  let expect = Json::object(Map::of([(
    "x",
    Json::object(Map::of([(
      "y",
      Json::object(Map::of([("z", Json::number(1.0, repr="1"))])),
    )])),
  )]))
  assert_eq(result, expect)
}

///|
test "simple table" {
  let result = parse_toml(
    #|[owner]
    |name = "Alice"
  )
  let expect = Json::object(Map::of([(
    "owner",
    Json::object(Map::of([("name", Json::string("Alice"))])),
  )]))
  assert_eq(result, expect)
}

///|
test "nested table" {
  let result = parse_toml(
    #|[database]
    |host = "localhost"
    |
    |[database.settings]
    |port = 5432
  )
  let nested = Json::object(Map::of([
    ("host", Json::string("localhost")),
    (
      "settings",
      Json::object(Map::of([("port", Json::number(5432.0, repr="5432"))])),
    ),
  ]))
  let expect = Json::object(Map::of([("database", nested)]))
  assert_eq(result, expect)
}

///|
test "duplicate key error" {
  try parse_toml(
    #|key = 1
    |key = 2
  ) catch {
    TomlError::ParseError(msg) => assert_true(msg.contains("duplicate key"))
  } noraise {
    _ => fail("expected error")
  }
}

///|
test "duplicate key in table" {
  try parse_toml(
    #|[t]
    |a = 1
    |a = 2
  ) catch {
    TomlError::ParseError(msg) => assert_true(msg.contains("duplicate key"))
  } noraise {
    _ => fail("expected error")
  }
}

///|
test "malformed table" {
  try parse_toml(
    #|[missing
  ) catch {
    TomlError::ParseError(msg) => assert_true(msg.contains("']'"))
  } noraise {
    _ => fail("expected error")
  }
}

///|
test "missing equals" {
  try parse_toml(
    #|key
  ) catch {
    TomlError::ParseError(msg) => assert_true(msg.contains("'='"))
  } noraise {
    _ => fail("expected error")
  }
}

///|
test "invalid value" {
  try parse_toml(
    #|key = [1, two]
  ) catch {
    TomlError::ParseError(msg) => assert_true(msg.contains("cannot parse"))
  } noraise {
    _ => fail("expected error")
  }
}

///|
test "roundtrip JSON stringify" {
  let result = parse_toml(
    #|title = "TOML Parser"
    |count = 3
    |enabled = true
    |tags = ["dev", "test"]
  )
  let json_str = result.stringify()
  // Should produce valid JSON
  assert_true(json_str.length() > 0)
  assert_true(json_str.contains("TOML Parser"))
  assert_true(json_str.contains("dev"))
}
"}

