{"path": "/private/tmp/prompt_demos/runs_flash-demos-plus/workspaces/01/cmd/tomljson/main.mbt", "content": "// CLI entry: tomljson [--stdin] [file]
// Reads TOML from a file or stdin and prints JSON to stdout.

async fn main {
  let args = @env.args()
  let (use_stdin, path) = parse_args(args)
  let input = if use_stdin {
    read_stdin()
  } else {
    @fs.read_file_to_string(path) catch {
      error =>
        @stdio.stderr.write("error: cannot read file '\{path}': \{error}\n")
        @sys.exit(1)
        return
    }
  }
  let json = @toml.parse_toml(input) catch {
    TomlError::ParseError(msg) =>
      @stdio.stderr.write("error: \{msg}\n")
      @sys.exit(1)
      return
  }
  println(json.stringify())
}

fn parse_args(args : Array[String]) -> (Bool, String) {
  let mut use_stdin = false
  let mut path = ""
  for i in 1..<args.length() {
    if args[i] is "--stdin" {
      use_stdin = true
    } else if path.is_empty() {
      path = args[i]
    }
  }
  if use_stdin {
    (true, "")
  } else if path.is_empty() {
    (false, "-") // will try to read file "-" if no args given
  } else {
    (false, path)
  }
}

fn read_stdin() -> String {
  // Uses C FFI to read from fd 0 (stdin)
  let buf = Bytes::make(4096)
  let mut result = StringBuilder::new()
  loop {
    let n = read_stdin_c(buf)
    if n <= 0 {
      break
    }
    result.write_bytes(buf.sub(0, n))
  }
  result.to_string()
}

fn read_stdin_c(buf : Bytes) -> Int {
  extern "C" read(Int, Bytes, Int) -> Int = "read"
  read_stdin_c(0, buf, buf.length())
}
"}

{"path": "/private/tmp/prompt_demos/runs_flash-demos-plus/workspaces/01/lib.mbt", "content": "// TOML subset parser — produces a deterministic JSON value.
// Supported:
//   - comments (#)
//   - blank lines and whitespace
//   - bare keys and dotted keys
//   - tables ([owner], [database.settings])
//   - string escapes: \", \\, \n, \t
//   - integers, booleans, arrays of those values
//   - duplicate-key errors with a useful message

///| Error type for parsing failures.
suberror TomlError {
  ParseError(String)
} derive(Debug)

///| Parse TOML text into a Json value.
/// Returns a Json::Object(map) where top-level tables are nested under their keys.
pub fn parse_toml(input : String) -> Json raise TomlError {
  let lines = input.split("\n")
  let root : Map[String, Json] = Map([], capacity=0)
  let current_table : Map[String, Json] = root

  for i in 0..<lines.length() {
    let line = lines[i]
    let trim = line.trim()

    // blank line or comment
    if trim.is_empty() || trim[0] is '#' {
      continue
    }

    // table header
    if trim[0] is '[' {
      let table_part = trim.sub(start=1, end=trim.length()).trim()
      let len = table_part.length()
      if len == 0 || table_part[len - 1] isnt ']' {
        raise TomlError::ParseError(
          "line \{i + 1}: malformed table header: missing ']'",
        )
      }
      let key_part = table_part.sub(start=0, end=len - 1).trim()
      let keys = split_dotted_key(key_part)
      // navigate to the nested table, creating empty maps as needed
      // We must re-traverse from root each time
      let mut tbl = root
      for j in 0..<keys.length() {
        let k = keys[j]
        if tbl.contains(k) {
          match tbl[k] {
            Json::Object(sub) => tbl = sub
            _ =>
              raise TomlError::ParseError(
                "line \{i + 1}: key '\{k}' is not a table",
              )
          }
        } else {
          let sub : Map[String, Json] = Map([], capacity=0)
          tbl[k] = Json::object(sub)
          tbl = sub
        }
      }
      continue
    }

    // key-value pair
    let eq_pos = find_unquoted_eq(trim)
    if eq_pos < 0 {
      raise TomlError::ParseError(
        "line \{i + 1}: invalid key-value pair: missing '='",
      )
    }
    let raw_key = trim.sub(start=0, end=eq_pos).trim()
    let raw_value = trim.sub(start=eq_pos + 1, end=trim.length()).trim()
    let keys = split_dotted_key(raw_key)
    let value = parse_value(raw_value, i + 1)

    // insert value into root, navigating dotted keys
    set_nested(root, keys, value)
  }

  Json::object(root)
}

///| Find first unquoted `=` outside of string literals.
fn find_unquoted_eq(s : StringView) -> Int {
  let mut in_str = false
  let mut i = 0
  while i < s.length() {
    match s.get_char(i) {
      Some('"') => in_str = !in_str
      Some('=') =>
        if !in_str {
          return i
        }
      _ => ()
    }
    i += 1
  }
  -1
}

///| Split a dotted key into parts.
fn split_dotted_key(key : StringView) -> Array[String] {
  let parts : Array[String] = []
  let mut start = 0
  let mut i = 0
  while i < key.length() {
    if key[i] is '.' {
      parts.push(key.sub(start=start, end=i).trim().to_owned())
      start = i + 1
    }
    i += 1
  }
  parts.push(key.sub(start=start, end=i).trim().to_owned())
  parts
}

///| Parse a TOML value into Json.
fn parse_value(s : StringView, line : Int) -> Json raise TomlError {
  let text = s.to_owned()
  // array
  if text.length() > 0 && text[0] is '[' {
    return parse_array(text, line)
  }
  // quoted string
  if text.length() > 0 && text[0] is '"' {
    return Json::string(parse_string(text, line))
  }
  // boolean
  if text == "true" {
    return Json::boolean(true)
  }
  if text == "false" {
    return Json::boolean(false)
  }
  // integer
  let n : Int = @string.from_str(text) catch {
    _ =>
      raise TomlError::ParseError(
        "line \{line}: cannot parse value: '\{text}'",
      )
  }
  Json::number(n.to_double(), repr=text)
}

///| Parse a TOML array.
fn parse_array(text : String, line : Int) -> Json raise TomlError {
  let len = text.length()
  if len < 2 {
    raise TomlError::ParseError("line \{line}: malformed array")
  }
  let inner = text.sub(start=1, end=len).trim()
  let inner_len = inner.length()
  if inner_len == 0 || inner[inner_len - 1] isnt ']' {
    raise TomlError::ParseError(
      "line \{line}: malformed array: missing ']'",
    )
  }
  let content = inner.sub(start=0, end=inner_len - 1).trim()
  if content.is_empty() {
    return Json::array([])
  }
  let arr : Array[Json] = []
  let mut i = 0
  let content_len = content.length()
  while i < content_len {
    // skip whitespace
    while i < content_len && content[i] is ' ' {
      i += 1
    }
    if i >= content_len {
      break
    }
    let start = i
    if content[i] is '"' {
      // string element: scan to closing "
      i += 1
      while i < content_len && content[i] isnt '"' {
        if content[i] is '\\' {
          i += 1 // skip escaped char
        }
        i += 1
      }
      i += 1 // closing "
    } else if content[i] is '[' {
      // nested array: count brackets
      let mut depth = 1
      i += 1
      while i < content_len && depth > 0 {
        if content[i] is '[' {
          depth += 1
        } else if content[i] is ']' {
          depth -= 1
        }
        i += 1
      }
    } else {
      // number, bool, etc – scan to comma or end
      while i < content_len && content[i] isnt ',' {
        i += 1
      }
    }
    let elem_text = if i < content_len && content[i] is ',' {
      content.sub(start=start, end=i).trim().to_owned()
    } else {
      content.sub(start=start, end=i).trim().to_owned()
    }
    arr.push(parse_value(elem_text, line))
    // skip comma
    if i < content_len && content[i] is ',' {
      i += 1
    }
  }
  Json::array(arr)
}

///| Parse a TOML quoted string, handling escapes.
fn parse_string(text : String, line : Int) -> String raise TomlError {
  let len = text.length()
  if len < 2 {
    raise TomlError::ParseError("line \{line}: expected quoted string")
  }
  match text.get_char(0) {
    None => raise TomlError::ParseError("line \{line}: empty string")
    Some(c) if c isnt '"' =>
      raise TomlError::ParseError("line \{line}: expected quoted string")
    _ => ()
  }
  match text.get_char(len - 1) {
    None =>
      raise TomlError::ParseError(
        "line \{line}: string missing closing quote",
      )
    Some(c) if c isnt '"' =>
      raise TomlError::ParseError(
        "line \{line}: string missing closing quote",
      )
