{"content": "// CLI entry: tomljson [--stdin] [file]
// Reads TOML from a file or stdin and prints JSON to stdout.

async fn main {
  let args = @env.args()
  let (use_stdin, path) = parse_args(args)
  let input = if use_stdin {
    read_stdin()
  } else {
    @fs.read_file_to_string(path) catch {
      error =>
        let msg = "error: cannot read file '" + path + "': " + error.to_string() + "\n"
        write_stderr(msg)
        @sys.exit(1)
        return
    }
  }
  let json = @toml.parse_toml(input) catch {
    TomlError::ParseError(msg) =>
      write_stderr("error: " + msg + "\n")
      @sys.exit(1)
      return
  }
  println(json.stringify())
}

fn parse_args(args : Array[String]) -> (Bool, String) {
  let mut use_stdin = false
  let mut path = ""
  for i in 1..<args.length() {
    if args[i] is "--stdin" {
      use_stdin = true
    } else if path.is_empty() {
      path = args[i]
    }
  }
  if use_stdin {
    (true, "")
  } else if path.is_empty() {
    // Use stdin by default when no path given
    (true, "")
  } else {
    (false, path)
  }
}

fn write_stderr(msg : String) -> Unit {
  let bytes = msg.to_bytes()
  let _ = write_stderr_c(bytes, bytes.length())
}

fn write_stderr_c(buf : Bytes, len : Int) -> Int {
  extern "C" write(Int, Bytes, Int) -> Int = "write"
  write_stderr_c(2, buf, len)
}

fn read_stdin() -> String {
  let result = StringBuilder()
  let buf = Bytes::make(4096)
  loop {
    let n = read_stdin_c(buf, buf.length())
    if n <= 0 {
      break
    }
    let chunk = buf.sub(0, n)
    for i in 0..<chunk.length() {
      result.write_char(chunk[i].to_char())
    }
  }
  result.to_string()
}

fn read_stdin_c(buf : Bytes, len : Int) -> Int {
  extern "C" read(Int, Bytes, Int) -> Int = "read"
  read_stdin_c(0, buf, len)
}
