{"content": "// TOML subset parser — produces a deterministic JSON value.
// Supported:
//   - comments (#)
//   - blank lines and whitespace
//   - bare keys and dotted keys
//   - tables ([owner], [database.settings])
//   - string escapes: \", \\, \n, \t
//   - integers, booleans, arrays of those values
//   - duplicate-key errors with a useful message

///| Error type for parsing failures.
suberror TomlError {
  ParseError(String)
} derive(Debug)

///| Parse TOML text into a Json value.
/// Returns a Json::Object(map) where top-level tables are nested under their keys.
pub fn parse_toml(input : String) -> Json raise TomlError {
  let lines : Array[StringView] = input.split("\n").to_array()
  let root : Map[String, Json] = Map([], capacity=0)

  for i in 0..<lines.length() {
    let line = lines[i]
    let trim = line.trim()

    // blank line or comment
    if trim.is_empty() {
      continue
    }
    let first_ch = trim.get_char(0)
    if first_ch is Some('#') {
      continue
    }

    // table header
    if first_ch is Some('[') {
      let table_part = trim.sub(start=1, end=trim.length()).trim()
      let tlen = table_part.length()
      if tlen == 0 {
        raise TomlError::ParseError(
          "line \{i + 1}: malformed table header",
        )
      }
      let last_ch = table_part.get_char(tlen - 1)
      if last_ch isnot Some(']') {
        raise TomlError::ParseError(
          "line \{i + 1}: malformed table header: missing ']'",
        )
      }
      let key_part = table_part.sub(start=0, end=tlen - 1).trim()
      let keys = split_dotted_key(key_part)
      // navigate/insert into root
      let mut tbl = root
      for j in 0..<keys.length() {
        let k = keys[j]
        if tbl.contains(k) {
          match tbl[k] {
            Json::Object(sub) => tbl = sub
            _ =>
              raise TomlError::ParseError(
                "line \{i + 1}: key '\{k}' is not a table",
              )
          }
        } else {
          let sub : Map[String, Json] = Map([], capacity=0)
          tbl[k] = Json::object(sub)
          tbl = sub
        }
      }
      continue
    }

    // key-value pair
    let eq_pos = find_unquoted_eq(trim)
    if eq_pos < 0 {
      raise TomlError::ParseError(
        "line \{i + 1}: invalid key-value pair: missing '='",
      )
    }
    let raw_key = trim.sub(start=0, end=eq_pos).trim()
    let raw_value = trim.sub(start=eq_pos + 1, end=trim.length()).trim()
    let keys = split_dotted_key(raw_key)
    let value = parse_value(raw_value, i + 1)
    set_nested(root, keys, value)
  }

  Json::object(root)
}

///| Find first unquoted `=` outside of string literals.
fn find_unquoted_eq(s : StringView) -> Int {
  let mut in_str = false
  let mut i = 0
  while i < s.length() {
    let ch = s.get_char(i)
    match ch {
      Some('"') => in_str = !in_str
      Some('=') =>
        if !in_str {
          return i
        }
      _ => ()
    }
    i += 1
  }
  -1
}

///| Split a dotted key into parts.
fn split_dotted_key(key : StringView) -> Array[String] {
  let parts : Array[String] = []
  let mut start = 0
  let mut i = 0
  while i < key.length() {
    let ch = key.get_char(i)
    if ch is Some('.') {
      parts.push(key.sub(start=start, end=i).trim().to_owned())
      start = i + 1
    }
    i += 1
  }
  parts.push(key.sub(start=start, end=i).trim().to_owned())
  parts
}

///| Parse a TOML value into Json.
fn parse_value(s : StringView, line : Int) -> Json raise TomlError {
  let text = s.to_owned()
  let first = text.get_char(0)
  // array
  if first is Some('[') {
    return parse_array(text, line)
  }
  // quoted string
  if first is Some('"') {
    return Json::string(parse_string(text, line))
  }
  // boolean
  if text == "true" {
    return Json::boolean(true)
  }
  if text == "false" {
    return Json::boolean(false)
  }
  // integer
  let n : Int = @string.from_str(text) catch {
    _ =>
      raise TomlError::ParseError(
        "line \{line}: cannot parse value: '\{text}'",
      )
  }
  Json::number(n.to_double(), repr=text)
}

///| Parse a TOML array.
fn parse_array(text : String, line : Int) -> Json raise TomlError {
  let len = text.length()
  if len < 2 {
    raise TomlError::ParseError("line \{line}: malformed array")
  }
  let inner = text.sub(start=1, end=len).trim()
  let inner_len = inner.length()
  if inner_len == 0 {
    raise TomlError::ParseError("line \{line}: malformed array")
  }
  let last_ch = inner.get_char(inner_len - 1)
  if last_ch isnot Some(']') {
    raise TomlError::ParseError(
      "line \{line}: malformed array: missing ']'",
    )
  }
  let content = inner.sub(start=0, end=inner_len - 1).trim()
  if content.is_empty() {
    return Json::array([])
  }
  let arr : Array[Json] = []
  let content_len = content.length()
  let mut i = 0
  while i < content_len {
    // skip whitespace
    while i < content_len {
      let c = content.get_char(i)
      if c is Some(' ') {
        i += 1
      } else {
        break
      }
    }
    if i >= content_len {
      break
    }
    let start = i
    let first_c = content.get_char(i)
    if first_c is Some('"') {
      // string element: scan to closing "
      i += 1
      while i < content_len {
        let c = content.get_char(i)
        if c is Some('\\') {
          i += 1
        } else if c is Some('"') {
          i += 1
          break
        }
        i += 1
      }
    } else if first_c is Some('[') {
      // nested array: count brackets
      let mut depth = 1
      i += 1
      while i < content_len && depth > 0 {
        let c = content.get_char(i)
        if c is Some('[') {
          depth += 1
        } else if c is Some(']') {
          depth -= 1
        }
        i += 1
      }
    } else {
      // number, bool, etc – scan to comma or end
      while i < content_len {
        let c = content.get_char(i)
        if c is Some(',') {
          break
        }
        i += 1
      }
    }
    let elem_text = content.sub(start=start, end=i).trim().to_owned()
    arr.push(parse_value(elem_text, line))
    // skip comma
    if i < content_len {
      let c = content.get_char(i)
      if c is Some(',') {
        i += 1
      }
    }
  }
  Json::array(arr)
}

///| Parse a TOML quoted string, handling escapes.
fn parse_string(text : String, line : Int) -> String raise TomlError {
