fn parse_or_result(input : String) -> Result[Json, String] {
  if input.is_empty() {
    Err("empty input")
  } else {
    try @toml.parse_toml(input) catch {
      _ => Err("parse failure")
    } noraise {
      json => Ok(json)
    }
  }
}

fn parse_args(args : Array[String]) -> (Bool, String) {
  let mut use_stdin = false
  let mut path = ""
  for i in 1..<args.length() {
    if args[i] is "--stdin" {
      use_stdin = true
    } else if path.is_empty() {
      path = args[i]
    }
  }
  if use_stdin || path.is_empty() {
    (true, "")
  } else {
    (false, path)
  }
}
